CREATE TABLE `votes_changes` (`id` BIGINT NOT NULL AUTO_INCREMENT , `owner_id` BIGINT NOT NULL , `created_at` BIGINT UNSIGNED NULL DEFAULT NULL , `caused_by` BIGINT NULL DEFAULT NULL , `caused_by_type` TINYINT UNSIGNED NOT NULL DEFAULT '0' , `old_value` DOUBLE UNSIGNED NULL DEFAULT NULL , `new_value` DOUBLE UNSIGNED NOT NULL , `is_rollbacked` TINYINT(1) UNSIGNED NOT NULL DEFAULT '0' , `action` TINYINT NOT NULL DEFAULT '0' , PRIMARY KEY (`id`)) ENGINE = InnoDB;
ALTER TABLE `apps` ADD `type` TINYINT UNSIGNED NULL DEFAULT '0' AFTER `deleted`;
